#include <stdio.h>

int main() {
    char ch;

    printf("알파벳을 입력하시오: ");
    scanf("%c", &ch);

    if (ch >= 'A' && ch <= 'Z')
        printf("변환: %c", ch + ('a' - 'A'));
    else if (ch >= 'a' && ch < 'z')
        printf("변환: %c", ch - ('a' - 'A'));
    else
        printf("알파벳이 아닙니다.");

    return 0;
}
```

**'a' - 'A'**가 뭘 의미하는지 정말 한참 고민했다..
알고보니 아스키코드표를 보면 영어에서 대문자 소문자 간에는 32라는 차이가 발생한다.
32라는 값을 정확히 외워서 쓸 수는 없으니 소문자와 대문자의 차이를 쉽게 풀어놓은 것!!
